# Log-log plot of mean |σ_ana − σ_num| vs δε for vertex-model getSigmaXX and getSigmaYY.
# Overlays A (δε)^2 (truncation) and B/δε (roundoff), fitted on p0=3.8. Separate figures.

import csv
import os

import matplotlib.pyplot as plt
import numpy as np

HERE = os.path.dirname(__file__)
LOCAL_FIG = os.path.join(HERE, "data")


def load_csv(path):
    by_p = {}
    with open(path) as f:
        for row in csv.DictReader(f):
            p0 = float(row["p0"])
            by_p.setdefault(p0, []).append(
                (float(row["deps"]), float(row["meanAbs"]))
            )
    for p0 in by_p:
        by_p[p0].sort()
    return by_p


def fit_power(x, y, exponent):
    """Least-squares A in y = A x^exponent, log-space mean of y / x^exp."""
    ratio = y / np.power(x, exponent)
    return np.exp(np.mean(np.log(ratio)))


def plot_component(csv_name, component, ylabel):
    path = os.path.join(LOCAL_FIG, csv_name)
    data = load_csv(path)
    colors = {3.7: "#1f77b4", 3.8: "#d62728", 3.9: "#2ca02c"}
    markers = {3.7: "o", 3.8: "s", 3.9: "^"}

    x38, y38 = np.array(data[3.8]).T
    left = (x38 >= 9e-5) & (x38 <= 1.1e-2)
    A = fit_power(x38[left], y38[left], 2.0)
    right = (x38 <= 1.1e-6) & (x38 >= 9e-9)
    B = fit_power(x38[right], y38[right], -1.0)

    xfit_left = np.logspace(-4.3, -1.9, 40)
    xfit_right = np.logspace(-8.2, -5.5, 40)
    fig, ax = plt.subplots(figsize=(6.2, 4.6))
    for p0 in sorted(data):
        x, y = np.array(data[p0]).T
        ax.loglog(
            x,
            y,
            marker=markers[p0],
            color=colors[p0],
            linestyle="-",
            linewidth=1.0,
            markersize=6,
            label=r"$p_0=%.1f$" % p0,
        )
    ax.loglog(
        xfit_left,
        A * xfit_left**2,
        "--",
        color="0.35",
        linewidth=1.4,
        label=r"$A\,(\delta\varepsilon)^2$",
    )
    ax.loglog(
        xfit_right,
        B / xfit_right,
        ":",
        color="0.15",
        linewidth=1.6,
        label=r"$B/\delta\varepsilon$",
    )
    ax.set_xlabel(r"$\delta\varepsilon$", fontsize=12)
    ax.set_ylabel(ylabel, fontsize=12)
    ax.set_xlim(5e-9, 2e-2)
    ax.legend(frameon=False, fontsize=10)
    ax.tick_params(which="both", direction="in")
    fig.tight_layout()

    os.makedirs(LOCAL_FIG, exist_ok=True)
    stem = "vertexSigma%s_pScan_abserr" % component
    fig.savefig(os.path.join(LOCAL_FIG, stem + ".pdf"))
    fig.savefig(os.path.join(LOCAL_FIG, stem + ".png"), dpi=200)
    plt.close(fig)
    print("%s  A (truncation) = %.6e" % (component, A))
    print("%s  B (roundoff)   = %.6e" % (component, B))
    print("wrote", os.path.join(LOCAL_FIG, stem + ".png"))


def main():
    plot_component(
        "vertexSigmaXX_pScan.csv",
        "XX",
        r"$\langle|\sigma_{xx}^{\mathrm{ana}}-\sigma_{xx}^{\mathrm{num}}|\rangle$",
    )
    plot_component(
        "vertexSigmaYY_pScan.csv",
        "YY",
        r"$\langle|\sigma_{yy}^{\mathrm{ana}}-\sigma_{yy}^{\mathrm{num}}|\rangle$",
    )


if __name__ == "__main__":
    main()
